"""Explain page block splitting, state copies and bounded collection budgets."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1861': ('네 칸짜리 긴 종이를 가운데에서 나누면 두 칸짜리 두 조각이 돼요. 메모리 블록도 더 작은 크기로 나누어 남은 조각과 함께 쓸 수 있어요.', '블록을 반으로 나누는 위치와 order 감소를 계산합니다.', '0·1·2·3번 페이지를 그려 [0,1]과 [2,3]으로 나누세요. 뒤 절반의 시작은 2번이에요.', ['order는 블록의 페이지 수를 정하는 단계예요. order 0은 1페이지, 1은 2페이지, 2는 4페이지예요. collect_split은 남아 있는 블록을 더 작은 크기로 나누는 함수예요.', '임시 목록 tmp의 order를 기존 collect.order보다 1 작게 정해요. order 2에서 1로 내리면 한 블록의 크기는 4페이지에서 2페이지로 줄어요. 원래 블록 하나에서 두 블록을 만들 수 있어요.', '원래 목록에서 블록 하나를 꺼내 page라는 포인터로 받아요. 앞 절반 시작은 &page[0], 뒤 절반 시작은 &page[1 << tmp.order]로 임시 목록에 넣어요. 1 << n은 이 경우 2의 n승을 구하는 식이에요.', 'order 2를 나눌 때 tmp.order는 1이고 1 << 1은 2예요. 따라서 뒤 절반은 &page[2], 즉 page + 2에서 시작해요. 0·1번이 앞 절반, 2·3번이 뒤 절반이에요.', 'page는 struct page를 가리켜요. struct page는 실제 메모리 페이지를 관리하는 설명 구조체예요. page + 2는 설명 구조체 두 항목만큼 이동한다는 뜻이지 실제 데이터 주소에 2바이트를 더하는 뜻이 아니에요.', '모든 남은 블록을 두 조각씩 tmp에 넣은 뒤 tmp의 상태를 collect로 복사해요. 결과적으로 블록 수는 두 배가 되고 각 블록의 order는 1 줄어요. 데이터 페이지 총수는 바뀌지 않아요. 이 설명은 나눌 수 있는 order가 1 이상인 정상 입력을 기준으로 해요.'], [('order 2인 네 페이지 블록을 반으로 나누면 뒤 절반 시작 포인터는 무엇인가요?', ['page에서 데이터 1바이트 뒤예요', 'page + 2, 즉 2번 페이지 설명 항목이에요'], '정답은 두 번째예요. 새 order는 1이라 절반은 2페이지예요. 포인터 계산 단위가 struct page 항목이라는 점도 함께 기억하세요.'), ('order가 1 이상일 때 split을 마치면 collect.order는 어떻게 되나요?', ['1 줄어요', '언제나 1 늘어요'], '정답은 첫 번째예요. tmp.order에 기존 값 - 1을 넣고 마지막에 상태를 복사해요. 블록은 더 작아지고 개수는 늘지만 전체 페이지 수는 같아요.')]), 'os1862': ('주소 목록을 새 목록으로 바꾸는 일과 그 주소의 물건을 모두 복사하는 일은 달라요. 가장 작은 한 페이지는 이 함수에서 더 나누지 않아요.', 'order 0의 종료 조건과 구조체 상태 복사를 이해합니다.', '한 페이지에서 멈추는 길과, 두 페이지 이상을 나눈 뒤 주소 목록만 바꾸는 길을 그리세요.', ['collect_split의 if (!collect.order)는 order가 0인지 묻는 조건이에요. order 0은 이미 한 페이지 블록이므로 바로 return해요. 이 함수는 반 페이지짜리 블록을 만드는 방식으로 계속 내려가지 않아요.', '임시 구조체 tmp를 선언할 때 order - 1을 계산하는 문장은 이 조건보다 앞에 있어요. 하지만 order 0이면 반환하므로 그 임시 음수 값을 이용해 블록을 나누거나 collect에 복사하지 않아요. 계산이 등장한 것과 그 값으로 후속 작업을 하는 것은 달라요.', 'order가 양수이면 기존 목록이 빌 때까지 블록을 꺼내고, 각 블록의 앞 절반과 뒤 절반 주소를 tmp에 넣어요. tmp는 새 크기의 블록 주소들을 모으는 임시 스택이에요.', '끝의 __memcpy(&collect, &tmp, sizeof(tmp))는 tmp 구조체 크기만큼 collect로 복사해요. &는 그 변수의 주소를 뜻하고 sizeof(tmp)는 구조체 자체가 차지하는 바이트 수예요.', '복사되는 것은 블록을 가리키는 포인터 배열과 index, order 같은 관리 상태예요. 포인터가 가리키는 모든 페이지의 실제 내용까지 따라가 복사하지는 않아요. 주소 쪽지 목록을 복사해도 그 주소의 집이 복제되지 않는 것과 같아요.', 'order 0에서는 이 마지막 복사에도 도달하지 않으므로 collect의 목록과 order가 그대로예요. 종이 예에서 한 페이지는 남겨 두고 두 페이지 블록만 두 한 페이지 블록으로 나누어 보세요.'], [('collect.order가 0이면 블록을 계속 쪼개나요?', ['네. 음수 order로 계속 나눠요', '아니요. 반환해 collect를 그대로 둬요'], '정답은 두 번째예요. 첫 조건에서 돌아가므로 분할 반복과 구조체 복사를 하지 않아요. tmp의 초기 계산만 보고 실제로 음수 크기의 분할을 한다고 생각하면 안 돼요.'), ('마지막 __memcpy는 무엇을 복사하나요?', ['포인터 목록·개수·order를 담은 smallstack 구조체예요', '포인터가 가리키는 모든 데이터 페이지의 내용이에요'], '정답은 첫 번째예요. 원본은 &tmp, 목적지는 &collect, 길이는 sizeof(tmp)예요. 주소를 복사하는 것과 그 주소의 내용까지 복사하는 것은 다르죠.')]), 'os1863': ('큰 조각끼리 먼저 세 개씩 묶고, 남은 조각은 반으로 나누어 작은 조각들과 다시 모아요. 크기를 맞춰야 같은 역할의 묶음을 만들 수 있어요.', '큰 order에서 작은 order로 내려가며 남은 블록을 재사용하는 순서를 이해합니다.', 'order 2에서 블록 하나가 남았다면 order 1 블록 둘로 나눠 다음 단계에 넘기는 화살표를 그리세요.', ['부팅 중 held_back에는 아직 한 묶음을 만들지 못한 shadow·origin 후보 블록이 남을 수 있어요. kmsan_memblock_discard는 초기 메모리 관리 단계를 마무리하며 이런 블록을 모아 가능한 데이터 페이지를 시스템에 돌려주려 해요.', '처음 collect.order를 MAX_PAGE_ORDER로 정하고 for 반복의 i도 그 최댓값부터 시작해요. i를 하나씩 줄여 0까지 진행해요. 큰 블록을 먼저 다루고 작은 블록으로 내려가는 순서예요.', '현재 order의 held_back.shadow와 origin이 있으면 collect 스택에 넣어요. 보관 포인터 둘은 NULL로 비워요. 다음 do_collection은 같은 크기 블록을 세 개씩 꺼내 하나는 데이터, 둘은 검사 정보로 연결해요.', '세 개씩 처리하면 남은 블록 수는 0, 1, 2 중 하나예요. order가 1 이상이면 collect_split이 남은 블록을 반으로 나누어요. 한 블록은 두 개, 두 블록은 네 개가 되어 다음 낮은 order 단계로 넘어가요.', '예를 들어 order 2의 네 페이지 블록 하나는 order 1의 두 페이지 블록 둘이 돼요. 다음 단계에서 원래 held_back에 있던 order 1 블록들과 합쳐 다시 세 개씩 묶을 기회를 얻어요. 크기가 다른 블록을 그대로 한 묶음에 넣는 것이 아니에요.', '마지막 order 0에서는 한 페이지보다 작게 나누지 않아요. 한두 페이지가 남으면 이 반복만으로 데이터·shadow·origin 세 역할을 완성할 수 없어요. discard라는 이름만 보고 남은 모든 페이지를 반드시 데이터로 반환한다고 해석하지 마세요.'], [('discard는 order를 어느 방향으로 처리하나요?', ['0에서 끝없이 큰 값으로 올라가요', '최대 order에서 시작해 0까지 내려가요'], '정답은 두 번째예요. for의 감소와 split의 크기 감소가 연결돼요. 큰 조각을 나눠 다음 단계의 작은 조각과 크기를 맞추려는 순서예요.'), ('order가 1 이상인 단계에서 한두 블록이 남으면 어떻게 다음 단계로 넘기나요?', ['각각 반으로 나눠 더 낮은 order의 블록으로 넘겨요', '검사 정보 없이 모두 곧바로 데이터로 반환해요'], '정답은 첫 번째예요. 데이터마다 shadow와 origin도 필요해서 세 개 묶음을 다시 만들어요. 단, 최소 order 0에서는 더 나누지 않으므로 같은 설명을 무한히 적용하면 안 돼요.')]), 'os1864': ('구슬 여덟 개를 세 개씩 묶으면 두 묶음과 두 개가 남아요. 각 묶음에서 하나는 데이터, 둘은 검사 정보라고 이름을 붙여 계산해요.', '제한된 수거 모형의 몫·나머지와 검증 범위를 이해합니다.', '여덟 칸을 데이터·shadow·origin 세 칸씩 두 묶음으로 나누고 남은 두 칸을 따로 표시하세요.', ['이 수업은 order 0부터 3까지의 작은 모형에서 페이지 수를 따로 세어 결과를 확인해요. 각 order에 보관한 블록이 0개·1개·2개인 경우를 비교하면 3×3×3×3=81가지 배치가 돼요.', '큰 블록은 필요하면 더 작은 블록으로 나누되 총 페이지 수는 유지해요. 세 역할을 묶을 때마다 같은 페이지 수가 데이터, shadow, origin으로 하나씩 배정돼요. 각 원본 페이지를 두 역할에 중복 배정하면 계산이 틀려요.', '총 남은 페이지가 N이면 이 모형의 예상 데이터 페이지 수는 N을 3으로 나눈 몫이에요. floor(N/3)라는 표기는 나눈 값에서 소수 부분을 버린 정수예요. 데이터와 같은 수의 페이지가 shadow와 origin에 각각 배정돼요.', 'N이 8이면 8 = 3×2 + 2예요. 데이터 2페이지, shadow 2페이지, origin 2페이지로 여섯 페이지를 쓰고 두 페이지가 남아요. 데이터 2와 남은 2만 더해 네 페이지가 전부라고 생각하면 검사 정보 네 페이지를 빠뜨린 거예요.', 'N%3은 3으로 나눈 나머지예요. 이런 총량 검산은 단계별 코드와 별도로 예상 결과를 구해 비교하는 기준이에요. 영어로 oracle이라고 부르기도 하지만 여기서는 결과를 대조할 정답 계산표라고 이해하면 돼요.', '81가지 모형을 확인해도 모든 Linux 설정과 실제 할당기·컴퓨터 동작을 시험한 것은 아니에요. 제한한 order와 유효한 배치의 수거 규칙을 검산한 거예요. 페이지 수뿐 아니라 각 페이지가 어떤 역할로 이동했는지도 확인해야 중복이나 누락을 찾을 수 있어요.'], [('총 8페이지인 이 수거 모형에서 데이터와 남은 페이지는 각각 얼마인가요?', ['8페이지 모두 데이터이고 남는 것은 없어요', '데이터 2페이지이고 2페이지가 남아요'], '정답은 두 번째예요. 나머지 4페이지는 shadow 2와 origin 2로 배정돼요. 2+2+2+2=8로 모든 역할과 나머지를 합쳐 확인하세요.'), ('order 0부터 3까지의 81가지 배치 모형을 통과하면 모든 실제 커널 동작도 검증한 건가요?', ['아니요. 정한 크기와 배치 모형의 범위에서 확인한 거예요', '네. 모든 order와 모든 하드웨어를 실행한 것과 같아요'], '정답은 첫 번째예요. 작은 모형으로 수거 규칙을 점검할 수 있지만 실제 부팅, 할당 실패, 모든 환경까지 실행한 것은 아니에요. 확인한 범위에 맞춰 결과를 해석해야 해요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_461.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
